/* Generated by charsets/generate_smallcaps.py from neo-smallcaps.json.
 * No runtime lookup tables. Keep original Neo-US text for exact source case.
 * Regular uses the 66-byte candidate's algorithm; digits retain 30–39.
 */
#ifndef OS3K_NEO_SMALLCAPS_H
#define OS3K_NEO_SMALLCAPS_H
#include <stdbool.h>
#include <stdint.h>

typedef enum {
    NEO_SMALLCAPS_REGULAR = 0,
    NEO_SMALLCAPS_BOLD = 1,
    NEO_SMALLCAPS_ITALIC = 2
} NeoSmallCapsStyle;

/* Fast path: source must be one of the 62 supported lowercase letters.
 * This is the measured 66-byte standalone algorithm; inlining can change size.
 */
static inline uint8_t NeoSmallCapsRegularFromLowercase(uint8_t source) {
    uint8_t regular;
    if (source & 0x20) regular = source ^ 0x2A;
    else regular = 0x40 | ((25 + (source >> 6) + ((source >> 1) & 3)) ^ 0x0A);
    if (!(source & 0x10) && ((0xACu >> (source & 7)) & 1)) regular ^= 0x2B;
    return regular;
}

/* Validate native lowercase letters. Zero means unsupported.
 * This is independent of private glyph decoding: the byte namespaces differ.
 */
static inline uint8_t NeoSmallCapsCanonicalSource(uint8_t source) {
    if ((source >= 0x61 && source <= 0x7A) ||
        (source >= 0xE0 && source <= 0xF6) || source >= 0xF8 ||
        source == 0x05 || source == 0x9A || source == 0x9C ||
        source == 0x9E || source == 0xDF) return source;
    return 0;
}

/* Checked source-to-private-Regular conversion. */
static inline uint8_t NeoSmallCapsRegularByte(uint8_t source) {
    source = NeoSmallCapsCanonicalSource(source);
    if (!source) return 0;
    return NeoSmallCapsRegularFromLowercase(source);
}

/* These helpers accept a known private Regular LETTER slot. */
static inline uint8_t NeoSmallCapsItalicFromRegular(uint8_t regular) {
    return regular ^ 0x2B;
}
static inline uint8_t NeoSmallCapsBoldFromRegular(uint8_t regular) {
    return regular ^ 0x40;
}

/* Caller supplies a known private Regular letter/digit, not a source byte. */
static inline uint8_t NeoSmallCapsStyleRegularByte(uint8_t regular, NeoSmallCapsStyle style) {
    if ((unsigned)style > NEO_SMALLCAPS_ITALIC) return 0;
    if (style == NEO_SMALLCAPS_REGULAR || (regular >= '0' && regular <= '9')) return regular;
    return style == NEO_SMALLCAPS_BOLD ? regular ^ 0x40 : regular ^ 0x2B;
}

static inline bool NeoSmallCapsEncodeByte(uint8_t source, NeoSmallCapsStyle style,
                                         uint8_t *output) {
    if (!output || (unsigned)style > NEO_SMALLCAPS_ITALIC) return false;
    uint8_t regular = NeoSmallCapsRegularByte(source);
    if (!regular) return false;
    *output = NeoSmallCapsStyleRegularByte(regular, style);
    return true;
}

static inline bool NeoSmallCapsDecodeByte(uint8_t glyph, uint8_t *output) {
    if (!output) return false;
    if (glyph >= '0' && glyph <= '9') { *output = glyph; return true; }
    unsigned value = (glyph & 0x20) ? glyph ^ 0x2B : glyph;
    unsigned index = ((value & 31) | ((value >> 2) & 32)) ^ 0x0A;
    uint8_t source;
    if (index >= 32) {
        if (index == 55) return false;
        source = index | 0xC0;
    } else if ((unsigned)(index - 1) < 26) source = index | 0x60;
    else if (index == 27) source = 0x05;
    else if (index == 31) source = 0xDF;
    else if (index >= 28 && index <= 30) source = (index << 1) + 0x62;
    else return false;
    uint8_t regular = NeoSmallCapsRegularFromLowercase(source);
    if (glyph != regular && glyph != (regular ^ 0x2B) && glyph != (regular ^ 0x40)) return false;
    *output = source;
    return true;
}
#endif
